insert into public.topics(id,course_id,title,description,emoji,position,is_active) values ('b1-healthy-lifestyle','b1-independent','Здоровый образ жизни','Обосновываем привычки и понимаем рекомендации о здоровье','🌿',5,true) on conflict(id) do update set course_id=excluded.course_id,title=excluded.title,description=excluded.description,emoji=excluded.emoji,position=excluded.position,is_active=excluded.is_active;
insert into public.lessons(id,topic_id,kind,title,plan_title,subtitle,description,minutes,emoji,position,is_active,theory_title,theory_sections,source_metadata) values
('b1health-words','b1-healthy-lifestyle','words','Co służy zdrowiu?','Привычки и самочувствие','8 карточек · B1','Расскажи о сне, питании, движении и отдыхе',9,'🌿',133,true,'','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-grammar','b1-healthy-lifestyle','grammar','Jak zmieniać nawyki?','Рекомендации и вид','6 заданий · B1','Давай общие советы и различай процесс с результатом',12,'✏️',134,true,'Безличные рекомендации и вид глагола','[["Общая рекомендация","Trzeba, warto, można и powinno się соединяются с инфинитивом и не называют конкретного исполнителя."],["Процесс","Несовершенный вид показывает повторение или длительность: regularnie ćwiczyć, ograniczać stres."],["Результат","Совершенный вид подчёркивает достигнутую границу: wykonać plan, zrezygnować z napojów."]]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-review','b1-healthy-lifestyle','review','Zmiana krok po kroku','Устойчивые изменения','7 карточек · B1','Обоснуй новую привычку и оцени результат',8,'🔄',135,true,'','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-quiz','b1-healthy-lifestyle','quiz','Quiz: zdrowy styl życia','Проверка темы','10 вопросов · B1','Проверь лексику, безличные советы и вид',9,'🎯',136,true,'','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-reading-check','b1-healthy-lifestyle','quiz','Czy rozumiesz zmianę Kuby?','Понимание текста','6 вопросов · B1','Найди ошибку, совет и результат нового плана',7,'📖',137,true,'','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}') on conflict(id) do update set topic_id=excluded.topic_id,kind=excluded.kind,title=excluded.title,plan_title=excluded.plan_title,subtitle=excluded.subtitle,description=excluded.description,minutes=excluded.minutes,emoji=excluded.emoji,position=excluded.position,is_active=excluded.is_active,theory_title=excluded.theory_title,theory_sections=excluded.theory_sections,source_metadata=excluded.source_metadata;
