('b1health-nawyk','nawyk','привычка','Dobry nawyk łatwiej utrzymać, gdy jest prosty.',437,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-tryb','tryb życia','образ жизни','Siedzący tryb życia może osłabiać organizm.',438,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-odzywiac','odżywiać się','питаться','Staram się odżywiać regularnie.',439,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-wysypiac','wysypiać się','высыпаться','Żeby mieć energię, trzeba się wysypiać.',440,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-ruch','aktywność fizyczna','физическая активность','Codzienna aktywność fizyczna poprawia nastrój.',441,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-odpoczynek','odpoczynek','отдых','Organizm potrzebuje również odpoczynku.',442,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-stres','radzić sobie ze stresem','справляться со стрессом','Spacer pomaga mi radzić sobie ze stresem.',443,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-regularnie','regularnie','регулярно','Lepiej ćwiczyć krótko, ale regularnie.',444,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-ograniczyc','ograniczyć','ограничить','Warto ograniczyć słodkie napoje.',445,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-zrezygnowac','zrezygnować z','отказаться от','Postanowił zrezygnować z późnych kolacji.',446,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-wprowadzac','wprowadzać zmianę','вводить изменение','Najlepiej wprowadzać jedną zmianę naraz.',447,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-utrzymac','utrzymać nawyk','сохранить привычку','Plan pomaga utrzymać nowy nawyk.',448,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-przemeczyc','przemęczać się','переутомляться','Nie powinno się przemęczać przed zawodami.',449,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-regeneracja','regeneracja','восстановление','Sen jest ważny dla regeneracji organizmu.',450,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1health-samopoczucie','samopoczucie','самочувствие','Po spacerze poprawiło mi się samopoczucie.',451,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}') on conflict(id) do update set polish=excluded.polish,translation=excluded.translation,example=excluded.example,position=excluded.position,is_active=excluded.is_active,source_metadata=excluded.source_metadata;
