insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values
('b1health-grammar','Żeby lepiej spać, warto ___ telefon godzinę przed snem.','["odłożyć","odkładać raz","położyć się telefon"]',0,'Однократная рекомендация с результатом требует совершенного вида odłożyć.',0),
('b1health-grammar','Przy zmianie nawyków nie powinno się ___.','["spieszyć","pospieszyć codziennie","spieszyć się wynik"]',0,'Безличная конструкция nie powinno się + инфинитив выражает общую рекомендацию.',1),
('b1health-grammar','Kiedy zaczynałem, ___ codziennie po dziesięć minut.','["ćwiczyłem","poćwiczyłem zawsze","ćwiczyć"]',0,'Повторяющееся действие в прошлом выражается несовершенным видом ćwiczyłem.',2),
('b1health-grammar','Dziś udało mi się ___ cały plan treningowy.','["wykonać","wykonywać co tydzień","wykonuję"]',0,'Завершённый результат после udało się выражается совершенным инфинитивом wykonać.',3),
('b1health-grammar','Составьте: Не следует менять все привычки одновременно.','["Nie powinno się zmieniać wszystkich nawyków jednocześnie.","Nie powinien zmienić wszystkie nawyki razem.","Nie powinno się zmienić wszystkich nawykami."]',0,'Общая рекомендация строится как nie powinno się + несовершенный инфинитив.',4),
('b1health-grammar','Составьте: Вчера мне удалось отказаться от сладких напитков.','["Wczoraj udało mi się zrezygnować ze słodkich napojów.","Wczoraj udawało mnie rezygnować słodkie napoje.","Wczoraj udałem się zrezygnuję od napojów."]',0,'Udało mi się + совершенный инфинитив передаёт достигнутый результат; zrezygnować требует z + родительный.',5),
('b1health-quiz','Что означает utrzymać nawyk?','["сохранить привычку","начать болезнь","изменить расписание врача"]',0,'Utrzymać nawyk — продолжать выбранное действие регулярно.',0),
('b1health-quiz','Aby mieć więcej energii, trzeba się ___.','["wysypiać","przemęczać","spieszyć"]',0,'Wysypiać się означает получать достаточно сна.',1),
('b1health-quiz','Wyберите естественное сочетание.','["radzić sobie ze stresem","robić regenerację do","odżywiać odpoczynek"]',0,'Radzić sobie ze stresem — устойчивое выражение «справляться со стрессом».',2),
('b1health-quiz','Nie powinno się ___ bez przerwy.','["pracować","przepracować codziennie","pracowało"]',0,'После безличного powinno się нужен инфинитив; длительное действие — pracować.',3),
('b1health-quiz','Wczoraj wreszcie ___ wszystkie ćwiczenia.','["wykonałem","wykonywałem i skończyłem raz","wykonywać"]',0,'Совершенный вид wykonałem подчёркивает завершённый набор упражнений.',4),
('b1health-quiz','Przez cały miesiąc ___ trzy razy w tygodniu.','["ćwiczyłam","poćwiczyłam zawsze","ćwiczę wczoraj"]',0,'Регулярный процесс в прошлом требует несовершенного вида ćwiczyłam.',5),
('b1health-quiz','Co pomaga bezpiecznie zmienić tryb życia?','["wprowadzanie jednej małej zmiany naraz","rezygnacja ze snu","bardzo intensywny trening pierwszego dnia"]',0,'Небольшие постепенные изменения легче и безопаснее поддерживать.',6),
('b1health-quiz','Lekarz poradził mi ___ słodkie napoje.','["ograniczyć","ograniczać jeden raz","ograniczony"]',0,'Рекомендация о конкретном результате использует совершенный инфинитив ograniczyć.',7),
('b1health-quiz','Kiedy należy odpocząć?','["Gdy organizm daje sygnały zmęczenia.","Dopiero po kilku nieprzespanych nocach.","Nigdy, jeśli mamy plan."]',0,'Отдых нужен при сигналах усталости, а не после переутомления.',8),
('b1health-quiz','Które zdanie opisuje trwały nawyk?','["Ćwiczę krótko, ale regularnie i zapisuję postępy.","Raz ćwiczę bardzo długo, potem miesiąc odpoczywam.","Codziennie wybieram zupełnie inny plan."]',0,'Регулярность и наблюдение за прогрессом помогают закрепить привычку.',9),
('b1health-reading-check','Dlaczego Kuba chciał zmienić tryb życia?','["Często był zmęczony i źle spał","Chciał wygrać zawodowy maraton","Lekarz zabronił mu chodzić"]',0,'Его беспокоили усталость и плохой сон.',0),
('b1health-reading-check','Jaki błąd popełnił na początku?','["Próbował zmienić wszystko jednocześnie","Ćwiczył tylko dziesięć minut","Poprosił o spokojną poradę"]',0,'Он взялся сразу за слишком много сложных изменений.',1),
('b1health-reading-check','Co poradziła mu fizjoterapeutka?','["Wybrać jeden mały nawyk i obserwować samopoczucie","Codziennie trenować do wyczerpania","Całkowicie zrezygnować z odpoczynku"]',0,'Специалист предложила начать с одного небольшого действия.',2),
('b1health-reading-check','Jaki pierwszy nawyk wybrał Kuba?','["Krótki spacer po pracy","Poranny intensywny bieg","Dwie godziny na siłowni"]',0,'Куба выбрал короткую прогулку после работы.',3),
('b1health-reading-check','Co zmieniło się po kilku tygodniach?','["Lepiej spał i miał więcej energii","Przestał wychodzić z domu","Codziennie bolały go mięśnie"]',0,'Регулярная прогулка улучшила сон и уровень энергии.',4),
('b1health-reading-check','Jaki jest główny wniosek tekstu?','["Trwała zmiana powstaje stopniowo i wymaga regeneracji","Zdrowie zależy tylko od silnej woli","Każdy powinien mieć identyczny plan"]',0,'Текст подчёркивает постепенность, наблюдение и восстановление.',5);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('b1health-maly-krok-kuby','b1-healthy-lifestyle','Mały krok Kuby','Почему устойчивые привычки начинаются с небольшого изменения','B1',8,'🌿','["Kuba pracował z domu i przez większość dnia siedział przed komputerem. Wieczorem był zmęczony, ale długo nie mógł zasnąć. Postanowił więc całkowicie zmienić tryb życia: kupił karnet na siłownię, zaplanował codzienne treningi i zrezygnował ze wszystkich ulubionych przekąsek.","Po trzech dniach bolały go mięśnie, brakowało mu energii, a ambitny plan zaczął go stresować. Kuba uznał, że ma za mało silnej woli. Znajoma fizjoterapeutka wyjaśniła jednak, że nie powinno się wprowadzać wszystkich zmian jednocześnie ani przemęczać organizmu.","Poradziła mu wybrać jeden prosty nawyk i przez dwa tygodnie obserwować samopoczucie. Kuba zdecydował, że po pracy będzie spacerował przez dwadzieścia minut. Nie chodziło o tempo ani wynik. Ważne było, żeby wychodzić regularnie, także w dni, kiedy miał mniej ochoty.","Po kilku tygodniach Kuba zauważył, że łatwiej zasypia i ma więcej energii rano. Dopiero wtedy ograniczył słodkie napoje i dodał dwa krótkie treningi w tygodniu. Zrozumiał, że zdrowy tryb życia nie polega na ciągłym wysiłku. Trwały nawyk wymaga czasu, realistycznego planu i odpowiedniej regeneracji."]','{"większość":{"lemma":"większość","translation":"большинство","part_of_speech":"существительное"},"zasnąć":{"lemma":"zasnąć","translation":"заснуть","part_of_speech":"глагол"},"karnet":{"lemma":"karnet","translation":"абонемент","part_of_speech":"существительное"},"przekąsek":{"lemma":"przekąska","translation":"перекус","part_of_speech":"существительное"},"brakowało":{"lemma":"brakować","translation":"не хватать","part_of_speech":"глагол"},"silnej woli":{"lemma":"silna wola","translation":"сила воли","part_of_speech":"выражение"},"fizjoterapeutka":{"lemma":"fizjoterapeutka","translation":"физиотерапевт","part_of_speech":"существительное"},"wprowadzać":{"lemma":"wprowadzać","translation":"вводить","part_of_speech":"глагол"},"przemęczać":{"lemma":"przemęczać się","translation":"переутомляться","part_of_speech":"глагол"},"obserwować":{"lemma":"obserwować","translation":"наблюдать","part_of_speech":"глагол"},"samopoczucie":{"lemma":"samopoczucie","translation":"самочувствие","part_of_speech":"существительное"},"tempo":{"lemma":"tempo","translation":"темп","part_of_speech":"существительное"},"ochoty":{"lemma":"ochota","translation":"желание","part_of_speech":"существительное"},"ograniczył":{"lemma":"ograniczyć","translation":"ограничить","part_of_speech":"глагол"},"wysiłku":{"lemma":"wysiłek","translation":"усилие; нагрузка","part_of_speech":"существительное"},"trwały":{"lemma":"trwały","translation":"устойчивый","part_of_speech":"прилагательное"},"regeneracji":{"lemma":"regeneracja","translation":"восстановление","part_of_speech":"существительное"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"b1health-reading-check"}',29,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
